        --text: #98ede4;
        --muted: #98ede4;
        --brand: #3fb950;
        --brand-fore: #ffffff;
        --border: #2b3138;
        --accent: #6cb6ff;
        --warn: #e3b341;
      }
      body {
        margin: 0;
        /*background: var(--bg);*/
        background: linear-gradient(135deg, #11998e 0%, #38ef7d 100%);
        color: var(--text);
        font: 16px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, Ubuntu,
          "Helvetica Neue", Arial;
      }
      a {
        color: var(--accent);
        text-decoration: none;
      }
      .container {
        max-width: 980px;
        margin: 40px auto;
        padding: 0 20px;
      }
      .header {
        display: flex;
        gap: 16px;
        align-items: center;
        margin-bottom: 28px;
      }
      .header h1 {
        margin: 0;
        font-size: 28px;
        font-weight: 500;
      }
      .verified {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        background: #0e1620;
        border: 1px solid #26303a;
        color: var(--muted);
        padding: 4px 10px;
        border-radius: 6px;
        font-size: 12px;
      }
      .twoCol {
        display: flex;
        gap: 24px;
        margin: 20px 0;
        align-items: stretch;
      }
      .colLeft {
        flex: 2;
      }
      .colRight {
        flex: 1.2;
      }
      .card {
        background: var(--panel);
        border: 1px solid var(--border);
        border-radius: 10px;
        padding: 20px;
      }
      .cardTitle {
        font-size: 18px;
        font-weight: 600;
        margin: 0 0 12px 0;
        letter-spacing: -0.2px;
      }
      .cardDesc {
        color: var(--muted);
        font-size: 14px;
        margin: 0 0 16px 0;
      }
      .inputGroup {
        display: flex;
        gap: 10px;
        align-items: center;
      }
      .inputGroup input {
        flex: 1;
        background: #0b0f14;
        border: 1px solid var(--border);
        border-radius: 8px;
        padding: 12px 14px;
        color: var(--text);
        font-family: monospace;
        font-size: 13px;
        outline: none;
      }
      .btn {
        background: var(--brand);
        border: none;
        border-radius: 8px;
        padding: 0 20px;
        height: 44px;
        font-weight: 600;
        font-size: 14px;
        color: var(--brand-fore);
        cursor: pointer;
        transition: opacity 0.15s;
      }
      .btn:hover {
        opacity: 0.9;
      }
      .reqList {
        margin: 8px 0 0 0;
        padding-left: 18px;
        font-size: 13px;
        line-height: 1.5;
        color: var(--muted);
      }
      .reqList li {
        margin: 6px 0;
      }
      .mainSection {
        margin: 24px 0;
      }
      .guideCard {
        background: var(--panel);
        border: 1px solid var(--border);
        border-radius: 10px;
        padding: 20px;
      }
      .guideTitle {
        font-size: 18px;
        font-weight: 600;
        margin: 0 0 16px 0;
      }
      .stepTitle {
        font-size: 16px;
        font-weight: 500;
        margin: 16px 0 8px 0;
      }
      .stepList {
        margin: 0;
        padding-left: 20px;
        font-size: 14px;
        line-height: 1.5;
      }
      .stepList li {
        margin: 6px 0;
      }
      .videoBox {
        margin-top: 20px;
        border-radius: 10px;
        overflow: hidden;
      }
      .videoBox video {
        width: 100%;
        display: block;
        border: 1px solid var(--border);
        border-radius: 10px;
      }
      .noteLine {
        border-left: 3px solid var(--warn);
        background: rgba(227, 179, 65, 0.06);
        padding: 10px 16px;
        font-size: 13px;
        margin: 20px 0 0 0;
        border-radius: 6px;
      }
      .footer {
        margin-top: 40px;
        padding-top: 18px;
        border-top: 1px solid var(--border);
        font-size: 12px;
        color: var(--muted);
        display: flex;
        flex-wrap: wrap;
        gap: 12px;
        justify-content: center;
      }
      .footer a {
        color: var(--muted);
        font-size: 12px;
      }
      .footer a:hover {
        color: var(--accent);
      }
      hr {
        border-color: var(--border);
        margin: 8px 0;
      }
      .smallText {
        font-size: 12px;
        color: var(--muted);
      }
