        var getRadomString = function(length) {
            var characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
            var randomString = '';
            for (var i = 0; i < length; i++) {
                randomString += characters[Math.floor(Math.random() * characters.length)];
            }
            return randomString;
